import test from 'node:test';import assert from 'node:assert/strict';import {followupDelta} from '../../reda-2/followup-delta.mjs';
const plan={id:'p',version:1,payload:{exercises:[{id:'e',name:'Benspark'}]}},boundary='2026-09-10T00:00:00Z',now='2026-09-19T00:00:00Z';
test('compares equal-length periods around a clinician boundary',()=>{const sessions=[{plan_id:'p',plan_version:1,status:'completed',started_at:'2026-09-05T12:00:00Z',payload:{exercises:[{exerciseId:'e',feedback:'heavy',status:'completed'}]}},{plan_id:'p',plan_version:1,status:'completed',started_at:'2026-09-15T12:00:00Z',payload:{exercises:[{exerciseId:'e',feedback:'okay',status:'completed'}]}}];const d=followupDelta({plan,boundary,now,sessions});assert.equal(d.valid,true);assert.ok(d.changes.some(x=>x.kind==='exercise'&&/ingen/.test(x.after)))});
test('surfaces factual count changes without calling them improvement',()=>{const d=followupDelta({plan,boundary,now,responses:[{plan_id:'p',plan_version:1,created_at:'2026-09-06T12:00:00Z',answers:{nextDay:'worse'}},{plan_id:'p',plan_version:1,created_at:'2026-09-16T12:00:00Z',answers:{nextDay:'settled'}}]});const x=d.changes.find(x=>x.kind==='symptoms');assert.deepEqual([x.before,x.after],[1,0]);assert.doesNotMatch(d.headline,/bättre|förbättr/)});
test('invalid or future boundary fails closed',()=>{assert.equal(followupDelta({plan,boundary:now,now}).valid,false);assert.equal(followupDelta({plan,boundary:'bad',now}).valid,false)});
